import re,os
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
for r in G['Demo pair 1 input']: print(''.join(str(x) for x in r))
print(G['Demo pair 1 output'])

I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
for r,row in enumerate(I):
    for c,x in enumerate(row):
        if x not in (3,8): print(r,c,x)

def out(I):
    h,w=len(I),len(I[0]); cnt=Counter(x for r in I for x in r)
    thr=h*w*0.05
    rare={c for c,n in cnt.items() if n<thr}
    def nrows(c): return sum(1 for r in range(h) if all(x==c or x in rare for x in I[r]))
    def ncols(c): return sum(1 for c2 in range(w) if all(I[r][c2]==c or I[r][c2] in rare for r in range(h)))
    bg=max((c for c in cnt if c not in rare), key=lambda c: nrows(c)+ncols(c))
    fill=Counter(x for r in I for x in r if x!=bg).most_common(1)[0][0]
    hrows=[r for r in range(h) if all(x!=fill for x in I[r])]
    vcols=[c for c in range(w) if all(I[r][c]!=fill for r in range(h))]
    res=[]
    for a,b in zip(hrows,hrows[1:]):
        row=[]
        for c1,c2 in zip(vcols,vcols[1:]):
            cs={I[a][c1],I[a][c2],I[b][c1],I[b][c2]}
            row.append(cs.pop() if len(cs)==1 and cs!={bg} else fill)
        res.append(row)
    return res
print(out(I)==O, out(I))
print(out(G['Test input']))

def transform(g):
    h,w=len(g),len(g[0]); cnt=Counter(x for r in g for x in r)
    thr=h*w*0.05
    rare={c for c,n in cnt.items() if n<thr}
    def nr(c): return sum(1 for r in range(h) if all(x==c or x in rare for x in g[r]))
    def nc(c): return sum(1 for c2 in range(w) if all(g[r][c2]==c or g[r][c2] in rare for r in range(h)))
    bg=max((c for c in cnt if c not in rare), key=lambda c: nr(c)+nc(c))
    fill=Counter(x for r in g for x in r if x!=bg).most_common(1)[0][0]
    marks={c for c in cnt if c not in (bg,fill)}
    hrows=[r for r in range(h) if all(x!=fill for x in g[r]) and any(x in marks for x in g[r])]
    vcols=[c for c in range(w) if all(g[r][c]!=fill for r in range(h)) and any(g[r][c] in marks for r in range(h))]
    res=[]
    for a,b in zip(hrows,hrows[1:]):
        row=[]
        for c1,c2 in zip(vcols,vcols[1:]):
            cs={g[a][c1],g[a][c2],g[b][c1],g[b][c2]}
            row.append(cs.pop() if len(cs)==1 and cs!={bg} else fill)
        res.append(row)
    return res
print(transform(I)==O)
print(transform(G['Test input']))
